18	/**
19	 * Maps Owner & OwnerDto using Mapstruct
20	 */
21	@Mapper(uses = PetMapper.class)
22	public interface OwnerMapper {
23	
24	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
25	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
26	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
27	    @Mapping(target = "membershipTier", expression = "java(resolveMembershipTier(owner))")
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    Owner toOwner(OwnerDto ownerDto);
31	
32	    /**
33	     * Formats the owner's stored names for display as {@code "LastName, FirstName"}.
34	     */
35	    default String formatDisplayName(Owner owner) {
36	        return owner.getLastName() + ", " + owner.getFirstName();
37	    }
38	
39	    /**
40	     * Formats the owner's initials as the upper-cased first letters of firstName and
41	     * lastName, dot-separated with a trailing dot, e.g. {@code "J.S."}.
42	     */
43	    default String formatInitials(Owner owner) {
44	        return initial(owner.getFirstName()) + initial(owner.getLastName());
45	    }
46	
47	    /** The upper-cased first letter of {@code name} followed by a dot. */
48	    private String initial(String name) {
49	        return Character.toUpperCase(name.charAt(0)) + ".";
50	    }
51	
52	    /**
53	     * Formats the owner's membership number as {@code "<customerCode>-M<YY>"}, where YY is the
54	     * last two digits of the registration date year, e.g. {@code "SMI-0007-M26"}.
55	     */
56	    default String formatMembershipNumber(Owner owner) {
57	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
58	    }
59	
60	    /**
61	     * Resolves the owner's membership tier: {@code SILVER} when the owner has no namesakes
62	     * (namesakeCount is 0) and an email is present, otherwise {@code BRONZE}.
63	     */
